`timescale 1ns/1ps

// The grading testbench for milestone 1: longer streams, overlap, a
// reset part-way through a half-finished pattern, and the width of the
// pulse.
module tb;

  logic clk = 1'b0;
  always #5 clk = ~clk;

  logic rst_n   = 1'b1;
  logic din     = 1'b0;
  logic [3:0] pattern = 4'b1011;
  logic found;

  seq_match dut (.clk(clk), .rst_n(rst_n), .din(din),
                 .pattern(pattern), .found(found));

  integer hits;
  integer i;

  // One cycle: drive at the falling edge, return just after the rising
  // one. `found` is a Moore output, so what it reads here is the value
  // produced by the edge that just happened.
  task tick(input logic b);
    begin
      @(negedge clk); din = b;
      @(posedge clk); #1;
      if (found) hits = hits + 1;
    end
  endtask

  task reset;
    begin
      @(negedge clk); rst_n = 1'b0; din = 1'b0;
      @(posedge clk); #1;
      rst_n = 1'b1;
      hits = 0;
    end
  endtask

  // The low `n` bits of `bits`, most significant first.
  task stream(input integer n, input [31:0] bits);
    begin
      for (i = n - 1; i >= 0; i = i - 1) tick(bits[i]);
    end
  endtask

  integer zeros_hits, long_hits, alt_hits, overlap_hits;
  integer runs_hits, ones_hits, partial_hits, split_hits;
  logic   quiet, pulse_low;
  integer early_hits, fourth_hits, other_hits, ones_pattern_hits;

  initial begin
    $dumpfile("dump.vcd");
    $dumpvars(0, tb);

    reset();
    quiet = found;
    tick(1'b0); tick(1'b0);
    zeros_hits = hits;

    reset();
    stream(18, 18'b101101101110101100);
    long_hits = hits;

    reset();
    stream(10, 10'b1010101010);
    alt_hits = hits;

    reset();
    stream(7, 7'b1011011);
    overlap_hits = hits;

    reset();
    stream(4, 4'b1011);
    tick(1'b0);
    pulse_low = found;

    reset();
    stream(8, 8'b10111011);
    runs_hits = hits;

    reset();
    stream(8, 8'b11111011);
    ones_hits = hits;

    reset();
    stream(3, 3'b101);
    partial_hits = hits;

    // Three quarters of the pattern, then a reset, then the last bit.
    reset();
    stream(3, 3'b101);
    @(negedge clk); rst_n = 1'b0;
    @(posedge clk); #1;
    rst_n = 1'b1;
    hits = 0;
    tick(1'b1);
    split_hits = hits;

    // The register is reset to zeros, and zeros must not be mistaken
    // for bits that arrived.
    pattern = 4'b0000;
    reset();
    tick(1'b0); tick(1'b0); tick(1'b0);
    early_hits = hits;
    tick(1'b0);
    fourth_hits = hits;

    // A different pattern, on the same hardware.
    pattern = 4'b1100;
    reset();
    stream(9, 9'b110011001);
    other_hits = hits;

    pattern = 4'b1111;
    reset();
    stream(6, 6'b111110);
    ones_pattern_hits = hits;

    $display("CHECK quiet_after_reset 0 %0d AT %0d", quiet, $time);
    $display("CHECK nothing_from_zeros 0 %0d AT %0d", zeros_hits, $time);
    $display("CHECK long_stream_hits 4 %0d AT %0d", long_hits, $time);
    $display("CHECK alternating_never_fires 0 %0d AT %0d", alt_hits, $time);
    $display("CHECK overlap_counts_twice 2 %0d AT %0d", overlap_hits, $time);
    $display("CHECK pulse_is_one_cycle 0 %0d AT %0d", pulse_low, $time);
    $display("CHECK two_in_10111011 2 %0d AT %0d", runs_hits, $time);
    $display("CHECK run_of_ones_then_1011 1 %0d AT %0d", ones_hits, $time);
    $display("CHECK partial_pattern_quiet 0 %0d AT %0d", partial_hits, $time);
    $display("CHECK reset_discards_progress 0 %0d AT %0d", split_hits, $time);
    $display("CHECK no_match_before_four_bits 0 %0d AT %0d", early_hits, $time);
    $display("CHECK matches_on_the_fourth 1 %0d AT %0d", fourth_hits, $time);
    $display("CHECK finds_pattern_1100_twice 2 %0d AT %0d", other_hits, $time);
    $display("CHECK finds_pattern_1111_twice 2 %0d AT %0d", ones_pattern_hits, $time);
    $display("DONE 14");
    $finish;
  end

endmodule

